using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class UtilityTests
{
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception("UTILITY FAIL: "+name);checks++;Console.WriteLine("UTILITY PASS: "+name);}static bool Near(double a,double b)=>Math.Abs(a-b)<.01;
 static UtilityDefinition D(string kind)=>UtilityCatalog.All.First(d=>d.Kind==kind);
 static DemoWorld W(string hull="mining_barge"){var w=new DemoWorld();w.NewGame(1);w.UtilityTrial(hull);w.Player.UtilityFit="";w.Player.Missiles=0;w.CargoItems.Clear();w.Player.Ore=0;w.Credits=100000;return w;}
 static string Hull(UtilityDefinition d)=>d.Role switch{"MiningTender"=>"mining_tender","ExpeditionCommand"=>"expedition_command","CapitalIndustrial"=>"industrial_cap","ExpeditionFrigate"=>"expedition_frigate",_=>"mining_barge"};
 static int Slot(UtilityDefinition d)=>d.Slot=="high"?0:d.Slot=="medium"?6:12;
 static UtilityState Install(DemoWorld w,UtilityDefinition d,int slot=-1){if(slot<0)slot=Slot(d);Check(w.FitUtility(d.Id,true,slot),"Fit "+d.Name);return w.Player.Utilities[slot];}
 static void Lock(DemoWorld w,string id){w.SelectedId=w.LockedId=id;var t=w.Locked!;w.Player.Position=t.Position-new Vector3(100,0,0);w.Player.Facing=Vector3.UnitX;}
 public static void Run(){checks=0;Check(UtilityCatalog.All.Length==43,"42 unique functional profiles");Check(UtilityCatalog.All.Select(d=>d.ReferenceTypeId).Distinct().Count()==43,"42 unique reference mappings");Check(UtilityPayloads.All.Length==13,"Probe, flare and nine prism payloads");
 foreach(var d in UtilityCatalog.All.Where(d=>d.Id!="ut_iris24")){var w=W(Hull(d));Check(ItemCatalog.Get(d.Id).Name==d.Name&&w.Offers(d.Id,w.SystemId,false).Any(),d.Name+" market/database");int slot=Slot(d);float stock=w.ItemCount(d.Id,true);var s=Install(w,d);Check(Near(w.ItemCount(d.Id,true),stock-1),d.Name+" stock consumed");Check(w.TotalFitCpu>=d.Cpu&&w.TotalFitPower>=d.Power,d.Name+" real fitting budget");Check(!w.FitUtility(d.Id,true,d.Slot=="high"?6:0),d.Name+" wrong socket rejected");Check(w.SetUtilityOnline(slot,false)&&!s.Effective,d.Name+" offline");Check(w.SetUtilityOnline(slot,true)&&s.Effective,d.Name+" online");Check(!w.ToggleUtility(slot),d.Name+" station activation blocked");w.EnterUtilityRange();s.Repeat=false;
 if(d.Passive){Check(!w.ToggleUtility(slot),d.Name+" passive activation blocked");}
 else{if(d.Harvest){string resource=d.Family=="Ice"?"ice":d.Family=="Gas"?"gas":d.Kind.Contains("Deep")?"deepore":"ore";Lock(w,"ut_resource_"+resource);if(d.Crystal){string payload="ut_crystal_"+resource+"_A";w.CargoItems[payload]=1;Check(w.LoadUtilityPayload(slot,payload),d.Name+" compatible crystal load");w.UpdateUtility(d.Reload+.1f);}float before=w.ItemCount(resource,false),rock=w.Locked!.Ore;Check(w.ToggleUtility(slot),d.Name+" activation");w.UpdateUtility(s.CycleDuration+.001f);Check(w.ItemCount(resource,false)>before,d.Name+" produces cargo");Check(w.Locked!.Ore<rock,d.Name+" finite deposit");}
 else if(d.Kind=="Compress"){w.CargoItems["ut_coolant"]=100;Check(!w.ToggleUtility(slot),d.Name+" core prerequisite");Check(w.ToggleIndustrialCore(),d.Name+" core deployed");Check(w.ToggleUtility(slot),d.Name+" service activated");string resource=d.Family switch{"Asteroid Ore"=>"ore","Deep Ore"=>"deepore","Moon Ore"=>"moonore","Gas"=>"gas",_=>"ice"};w.CargoItems[resource]=2;if(resource=="ore")w.Player.Ore=2;float volume=w.CargoUsed;Check(w.CompressUtility(resource,2),d.Name+" compression");Check(Near(w.ItemCount(resource,false),0)&&Near(w.ItemCount("compressed_"+resource,false),2)&&w.CargoUsed<volume,d.Name+" lossless smaller cargo");string grid=w.Grid;w.WarpNext();Check(w.Grid==grid&&!w.CanUseGate("player"),d.Name+" deployed interlock");w.ToggleIndustrialCore();w.UpdateUtility(61);Check(!w.IndustrialCore&&!s.Active,d.Name+" core stops at cycle boundary");}
 else if(d.Kind is "CoreProbe" or "CombatProbe"){string payload=d.Kind=="CoreProbe"?"ut_probe_core":"ut_probe_combat";w.CargoItems[payload]=8;Check(w.LoadUtilityPayload(slot,payload),d.Name+" load eight probes");w.UpdateUtility(d.Reload+.1f);Check(w.ToggleUtility(slot),d.Name+" launch cycle");w.UpdateUtility(d.Cycle+.01f);Check(w.ScanProbes.Count==8&&s.Loaded==0,d.Name+" deployed real consumables");Check(w.AnalyzeUtilityProbes(),d.Name+" analyze formation");w.UpdateUtility(11);var site=w.UtilitySites.First(x=>x.Kind=="Data");w.ProbeSelection=site.Id;w.ProbeCenter=new(site.X,site.Y,site.Z);w.ProbeRange=.25f;w.AnalyzeUtilityProbes();w.UpdateUtility(11);Check(site.Signal==100,d.Name+" centered narrow scan resolves");var shipSite=w.UtilitySites.First(x=>x.Kind=="Ship");w.ProbeCenter=new(shipSite.X,shipSite.Y,shipSite.Z);w.AnalyzeUtilityProbes();w.UpdateUtility(11);Check(shipSite.Signal==(d.Kind=="CombatProbe"?100:0),d.Name+" core/combat filtering");w.RecallUtilityProbes();w.UpdateUtility(3.1f);Check(w.ScanProbes.Count==0&&w.ItemCount(payload,false)==8,d.Name+" recovery returns real probes");}
 else if(d.Analyzer){Lock(w,d.Kind=="Relic"?"ut_Relic":"ut_Data");Check(w.ToggleUtility(slot),d.Name+" correct site activation");Check(w.UtilityHackState?.Coherence==d.VirusCoherence&&w.UtilityHackState.Strength==d.VirusStrength,d.Name+" virus attributes");w.FailUtilityHack();Check(w.Locked!.HackAttempts==1,d.Name+" failed attempt recorded");Check(w.ToggleUtility(slot),d.Name+" second attempt");w.FailUtilityHack();Check(!w.Targets.First(t=>t.Id==s.TargetId||t.Id==(d.Kind=="Relic"?"ut_Relic":"ut_Data")).Alive,d.Name+" second failure destroys container");}
 else {string id=d.Kind=="SurveyProbe"?"ut_Moon":d.Kind is "Salvage" or "Tractor"?"ut_wreck":"ut_Data";Lock(w,id);if(d.Kind is "SurveyProbe" or "Festival"){string payload=d.Kind=="Festival"?"ut_firework":"ut_probe_survey";w.CargoItems[payload]=3;Check(w.LoadUtilityPayload(slot,payload),d.Name+" consumable loaded");w.UpdateUtility(d.Reload+.01f);}Check(w.ToggleUtility(slot),d.Name+" utility activation");float hull=w.Locked!.Hull;w.UpdateUtility(s.CycleDuration+.01f);Check(!s.Active,d.Name+" single cycle stops");if(d.Kind is "CargoScan" or "ShipScan" or "SurveyProbe")Check(w.UtilityReports.Count>0,d.Name+" inspection report");if(d.Kind=="Festival")Check(w.Locked.Hull==hull&&s.Loaded==2&&w.WeaponVisuals.Count>0,"Festival consumes flare, renders and causes no damage");}}
 w.Screen=ViewMode.Station;Check(w.UnfitUtility(slot)&&w.ItemCount(d.Id,true)==stock,d.Name+" unfit returns module");}
 // Fitting interactions and group limits.
 var budget=W();Install(budget,D("Miner"));double cpu=budget.TotalFitCpu;Install(budget,D("OreUpgrade"));Check(budget.TotalFitCpu>cpu+D("OreUpgrade").Cpu,"Ore governor increases harvester CPU");budget.Player.SetStat("cpuOutput",budget.TotalFitCpu-1);Check(!budget.FitUtility(D("OreUpgrade").Id,true,13),"Upgrade budget rejection is atomic");var chipset=W();Install(chipset,D("Chipset"));Check(!chipset.FitUtility(D("Chipset").Id,true,7),"One survey chipset maximum");chipset.Player.SetStat("hiSlots",1);Check(chipset.FitError(WeaponCatalog.Get("rail"),0).Length>0,"Weapons count utility high sockets");var wrong=W("frigate");Check(!wrong.FitUtility(D("Strip").Id,true,0),"Strip harvester role restriction");
 // Partial cycles versus gas committed cycles, whole ice blocks, cargo overflow.
 var partial=W();var miner=Install(partial,D("Miner"));partial.EnterUtilityRange();Lock(partial,"ut_resource_ore");partial.ToggleUtility(0);partial.UpdateUtility(miner.CycleDuration*.5f);partial.ToggleUtility(0);Check(partial.Player.Ore>0&&!miner.Active,"Mining stop returns earned partial yield");var gas=W();var scoop=Install(gas,D("GasScoop"));gas.EnterUtilityRange();Lock(gas,"ut_resource_gas");gas.ToggleUtility(0);gas.UpdateUtility(scoop.CycleDuration*.5f);gas.ToggleUtility(0);Check(scoop.Active&&gas.ItemCount("gas",false)==0,"Gas stop waits for paid cycle");gas.UpdateUtility(scoop.CycleLeft+.01f);Check(!scoop.Active&&gas.ItemCount("gas",false)>0,"Gas finishes committed cycle");
 var crystals=W();var prism=Install(crystals,D("CrystalStrip"));crystals.Hangar["ut_crystal_ore_A"]=1;crystals.LoadUtilityPayload(0,"ut_crystal_ore_A");prism.CrystalWear=.6f;crystals.UnfitUtility(0);Check(crystals.CrystalConditions.Count==1,"Crystal wear survives unloading");Install(crystals,D("CrystalStrip"));Check(crystals.Player.Utilities[0].ReloadLeft>0,"Refit preserves committed reload timer");crystals.UpdateUtility(crystals.Player.Utilities[0].ReloadLeft+.01f);Check(crystals.LoadUtilityPayload(0,"ut_crystal_ore_A"),"Reloaded prism accepts returned crystal");Check(Near(crystals.Player.Utilities[0].CrystalWear,.6),"Crystal condition follows actual inventory");
 // Tractor ownership and motion; salvage fails without destroying material.
 var tractor=W();var beam=Install(tractor,D("Tractor"));tractor.EnterUtilityRange();Lock(tractor,"ut_wreck");var wreck=tractor.Locked!;wreck.Position=tractor.Player.Position+new Vector3(6000,0,0);float distance=Vector3.Distance(wreck.Position,tractor.Player.Position);tractor.ToggleUtility(0);tractor.UpdateUtility(1);Check(Vector3.Distance(wreck.Position,tractor.Player.Position)<distance,"Tractor moves wreck at real speed");tractor.StopUtility(beam);wreck.OwnerId="other";Check(!tractor.ToggleUtility(0),"Tractor refuses unowned wreck");
 var salvage=W();var salvager=Install(salvage,D("Salvage"));salvage.EnterUtilityRange();Lock(salvage,"ut_wreck");salvager.Repeat=false;for(int i=0;i<100&&salvage.Locked!=null;i++){salvage.Player.Cap=salvage.Player.MaxCap;salvage.ToggleUtility(0);salvage.UpdateUtility(salvager.CycleDuration+.01f);}Check(salvage.ItemCount("salvage",false)==20,"Salvager recovers finite wreck yield");
 // Frontier, defenses, cache limit, tools and success loot.
 var hack=W();var analyzer=Install(hack,D("Data"));hack.EnterUtilityRange();Lock(hack,"ut_Data");hack.ToggleUtility(6);var h=hack.UtilityHackState!;Check(!hack.ClickUtilityHack(40),"Hacking cannot skip frontier");for(int i=1;i<48;i++)h.Nodes[i]=new(){Kind="Empty"};for(int i=1;i<48;i++)hack.ClickUtilityHack(i);Check(hack.ClickUtilityHack(48),"Reach and reveal core");for(int i=0;i<5&&!h.Complete;i++)hack.ClickUtilityHack(48);Check(h.Won&&hack.Locked!.Hacked,"Destroying core unlocks container");float loot=hack.ItemCount("salvage",false);hack.LootUtilityTarget();Check(hack.ItemCount("salvage",false)>loot,"Loot moves actual container contents");
 // Persistence retains active rack, targets, core, crystal state and probes.
 var save=W("mining_tender");Install(save,UtilityCatalog.All.First(d=>d.Kind=="Compress"&&d.Role=="MiningTender"));save.CargoItems["ut_coolant"]=100;save.EnterUtilityRange();save.ToggleIndustrialCore();save.ToggleUtility(0);save.ScanProbes.Add(new(){System=save.SystemId,Life=120});save.Targets.First(t=>t.SiteKind=="Data").HackAttempts=1;save.Save();var load=new DemoWorld();Check(load.Load(),"Utility save loads");Check(load.Player.Utilities[0].Active&&load.IndustrialCore&&Near(load.CoreLeft,60),"Compression cycles persist");Check(load.ScanProbes.Count==1&&Near(load.ScanProbes[0].Life,120),"Deployed probes persist");Check(load.Targets.First(t=>t.SiteKind=="Data").HackAttempts==1,"Container attempts persist");
 var cargoPayload=W();Install(cargoPayload,D("CoreProbe"));cargoPayload.Hangar["ut_probe_core"]=0;cargoPayload.CargoItems["ut_probe_core"]=8;Check(cargoPayload.LoadUtilityPayload(0,"ut_probe_core",false)&&cargoPayload.Player.Utilities[0].Loaded==8&&cargoPayload.ItemCount("ut_probe_core",false)==0,"Docked cargo-origin payload loading");
 var campaign=W();campaign.EnterUtilityRange();campaign.WeaponTestMode=false;campaign.Grid="utility_site";campaign.Targets.RemoveAll(t=>t.Kind!=TargetKind.Asteroid);campaign.Save();var campaignLoad=new DemoWorld();Check(campaignLoad.Load()&&campaignLoad.Targets.Count==5&&campaignLoad.Targets.All(t=>t.Kind==TargetKind.Asteroid),"Campaign exploration targets restore without phantom station");
 // Deterministic mechanics contracts, using forced chances while preserving shipped balance.
 foreach(string kind in new[]{"Miner","DeepMiner","CrystalStrip"}){var original=D(kind);try{UtilityCatalog.ById[original.Id]=original with{CritChance=1,ResidueChance=0,CloudChance=0};var cw=W();var cs=Install(cw,original);cw.EnterUtilityRange();Lock(cw,"ut_resource_ore");cs.TargetId=cw.LockedId;float rock=cw.Locked!.Ore;cw.FinishUtilityHarvest(cs,1);float depletion=rock-cw.Locked.Ore;Check(cw.Player.Ore>depletion&&cs.Criticals==1,kind+" critical bonus is free additional ore");}finally{UtilityCatalog.ById[original.Id]=original;}}
 var residueDef=D("Miner");try{UtilityCatalog.ById[residueDef.Id]=residueDef with{CritChance=0,ResidueChance=1,ResidueVolume=1};var rw=W();var rs=Install(rw,residueDef);rw.EnterUtilityRange();Lock(rw,"ut_resource_ore");rs.TargetId=rw.LockedId;float rock=rw.Locked!.Ore;rw.FinishUtilityHarvest(rs,1);Check(rs.Residue>0&&Near(rock-rw.Locked.Ore,rw.Player.Ore+rs.Residue),"Residue depletes extra deposit without cargo");}finally{UtilityCatalog.ById[residueDef.Id]=residueDef;}
 var fleet=W("mining_tender");Install(fleet,UtilityCatalog.All.First(d=>d.Kind=="Compress"&&d.Family=="Asteroid Ore"&&d.Role=="MiningTender"));fleet.HireWingmate("Escort");fleet.CargoItems["ut_coolant"]=100;fleet.Player.Ore=100;fleet.EnterUtilityRange();var wing=fleet.Wingmates[0];var wt=fleet.Targets.First(t=>t.Id==wing.Id);wt.Position=fleet.Player.Position+new Vector3(1000,0,0);Check(fleet.TransferUtilityFleetCargo(wing.Id,"ore",100,true)&&fleet.Player.Ore==0,"Fleet transfer consumes source cargo");fleet.ToggleIndustrialCore();fleet.ToggleUtility(0);Check(fleet.CompressUtilityFleet(wing.Id,"ore",100)&&wing.UtilityCargo["compressed_ore"]==100,"Active in-range fleet compression service");wt.Position+=new Vector3(1000000,0,0);wing.UtilityCargo["ore"]=1;Check(!fleet.CompressUtilityFleet(wing.Id,"ore",1),"Fleet compression rejects out-of-range member");
 var expiration=W();expiration.EnterUtilityRange();expiration.ScanProbes.Add(new(){System=expiration.SystemId,Life=1});expiration.UpdateUtility(2);Check(expiration.ScanProbes.Count==0&&expiration.ItemCount("ut_probe_core",false)==1,"Expired probes auto-recover into free cargo");
 var passive=W();Install(passive,D("Strength"));Check(passive.Player.Stat("probeStrength")>28,"Probe support changes live hull stats");Install(passive,D("ScanTime"),7);Check(passive.Player.Stat("probeScanTime")<8,"Acquisition support changes live scan cadence");
 Console.WriteLine($"{checks} exploration, mining and utility checks passed.");}
}
